<?php
require_once __DIR__.'/../config/auth.php';require_role('owner');$pdo=db();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$cashier=(int)($_GET['cashier']??0);$sql="SELECT DATE(t.created_at) tanggal,COUNT(*) transaksi,SUM(t.total) omzet,SUM(t.profit) laba,SUM((SELECT SUM(quantity) FROM transaction_details WHERE transaction_id=t.id)) produk FROM transactions t WHERE t.status='paid' AND t.branch_id=? AND DATE(t.created_at) BETWEEN ? AND ?";$args=[branch_id(),$from,$to];if($cashier){$sql.=' AND t.cashier_id=?';$args[]=$cashier;}$sql.=' GROUP BY DATE(t.created_at) ORDER BY tanggal';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();$tot=['omzet'=>0,'laba'=>0,'transaksi'=>0,'produk'=>0];foreach($rows as $r)foreach($tot as $k=>$_)$tot[$k]+=(float)$r[$k];$s=$pdo->prepare("SELECT id,name FROM users WHERE role='kasir' AND branch_id=? ORDER BY name");$s->execute([branch_id()]);$cashiers=$s->fetchAll();$pageTitle='Laporan Cabang';$active='laporan';include __DIR__.'/../includes/header.php';?>
<section class="card"><form class="filter-row"><label>Dari<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="to" value="<?=e($to)?>"></label><label>Kasir<select name="cashier"><option value="0">Semua</option><?php foreach($cashiers as $c):?><option value="<?=$c['id']?>" <?=$cashier===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><button class="btn primary">Terapkan</button></form></section><div class="grid stats" style="margin-top:18px"><div class="stat-card"><small>Omzet</small><strong><?=rupiah($tot['omzet'])?></strong></div><div class="stat-card"><small>Laba kotor</small><strong><?=rupiah($tot['laba'])?></strong></div><div class="stat-card"><small>Transaksi</small><strong><?=$tot['transaksi']?></strong></div><div class="stat-card"><small>Produk terjual</small><strong><?=$tot['produk']?></strong></div></div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Transaksi</th><th>Produk</th><th>Omzet</th><th>Laba</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=date('d M Y',strtotime($r['tanggal']))?></td><td><?=$r['transaksi']?></td><td><?=$r['produk']?></td><td><?=rupiah($r['omzet'])?></td><td><?=rupiah($r['laba'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/../includes/footer.php';?>
